interface TileRepository { String find(String id); }
class DatabaseRepository implements TileRepository {
    public String find(String id) { return "db:" + id; }
}
class TileService {
    private final TileRepository repository;
    TileService(TileRepository repository) { this.repository = repository; }
    String load(String id) { return repository.find(id); }
}
public class LooseCouplingDemo {
    public static void main(String[] args) { System.out.println(new TileService(new DatabaseRepository()).load("42")); }
}
